//! The measurement of the pre-run (ADR-0020 section 3, design note of the measurement): over
//! the living, per trait the mean and the population spread (divisor `n`) of the additive
//! value `A`, both sums in ascending lineage key; per additive locus the mean dose.
//!
//! The expected values come from `tools/state_reference.py` and `tools/world_reference.py`,
//! written from the design note and not from this code.
//!
//! Scenario "measure": the test map `tests/golden/data_traits` (four traits, `test:face`
//! includes `test:growth`; the additive loci `test:g1`, `test:f1`, `test:p1` and the
//! threshold locus `test:g2`, which is not measured), seed 0xff, founder tag `test:measure`,
//! the switch off, ten founders in four couples and two singles, 30 years; measured right
//! after the start, around the first birth and the first death, in year 10 and at the end.
//! The other measurements read pinned saves of "threshold", "similar" (run on to 30 years
//! as "similar_long") and "mortal".

mod common;

use sim_core::data::Data;
use sim_core::data_id::DataId;
use sim_core::genome::{Genome, LocusAlleles, Sex};
use sim_core::input::{Couple, Founder, Input, Start};
use sim_core::params::WorldParams;
use sim_core::time::SimTime;
use sim_core::world::{World, YearOut};

const Y: i64 = 31_449_600;

/// The saves of a scenario with their measurements.
type Saves = &'static [(&'static str, Expected)];

/// A scenario of loaded saves: its name, its data and its saves.
type Loaded = (&'static str, fn() -> Data, Saves);

/// Doses at (`test:g1`, `test:f1`, `test:g2`, `test:p1`) and per trait `A` and `G` bits.
type AdditiveCase = ([u8; 4], [(&'static str, u64, u64); 4]);

/// One measurement: the living, then per trait (id, mean bits, sigma bits), per locus
/// (id, mean dose bits).
struct Expected {
    living: u64,
    traits: &'static [(&'static str, u64, u64)],
    loci: &'static [(&'static str, u64)],
}

