fn assert_measures(world: &World, expected: &Expected, case: &str) {
    let measurement = world.state().measure().expect("somebody lives");
    assert_eq!(measurement.living, expected.living, "{case}");
    let traits: Vec<(String, u64, u64)> = measurement
        .traits
        .iter()
        .map(|t| {
            (
                t.trait_id.as_str().to_owned(),
                t.mean.to_bits(),
                t.sigma.to_bits(),
            )
        })
        .collect();
    let want: Vec<(String, u64, u64)> = expected
        .traits
        .iter()
        .map(|(t, mean, sigma)| ((*t).to_owned(), *mean, *sigma))
        .collect();
    assert_eq!(traits, want, "{case}");
    let loci: Vec<(String, u64)> = measurement
        .loci
        .iter()
        .map(|l| (l.locus.as_str().to_owned(), l.mean_dose.to_bits()))
        .collect();
    let want: Vec<(String, u64)> = expected
        .loci
        .iter()
        .map(|(l, dose)| ((*l).to_owned(), *dose))
        .collect();
    assert_eq!(loci, want, "{case}");
}

fn alleles(list: &[(&str, [u8; 2])]) -> Vec<LocusAlleles> {
    list.iter()
        .map(|(locus, copies)| LocusAlleles {
            locus: id(locus),
            copies: copies.to_vec(),
        })
        .collect()
}

fn founder(years: i64, sex: Sex, list: &[(&str, [u8; 2])]) -> Founder {
    Founder {
        born: SimTime::from_secs(-years * Y),
        sex,
        alleles: alleles(list),
    }
}

