/// "measure": the run reaches the reference's saves, and at each clock the measurement is
/// the reference's.
#[test]
fn the_measurement_of_a_run_is_the_references() {
    let mut world = World::new(traits_data());
    world.submit(measure_start()).expect("accepted");
    world.take_log();
    let mut out = YearOut::default();
    for (clock, save, expected) in &TRAITS_CLOCKS {
        if *clock >= 0 {
            world.advance_until(&mut out, SimTime::from_secs(*clock), &mut |_| false);
            world.take_log();
        }
        assert_eq!(
            world.save(&out.year_hashes).expect("saves"),
            hex(save),
            "{clock}"
        );
        assert_measures(&world, expected, &format!("measure at {clock}"));
    }
}

/// Saves of other scenarios, loaded: the threshold map (`A` is `Σ (d − 1)` over the eight
/// liability loci), the pairing town at its start, after ten rounds and run on to 30 years,
/// and "mortal" at its start (a map without traits and additive loci: both lists empty).
#[test]
fn the_measurement_of_loaded_saves_is_the_references() {
    let cases: [Loaded; 4] = [
        ("threshold", liability_data, &THRESHOLD_SAVES),
        ("similar", similar_data, &SIMILAR_SAVES),
        ("similar_long", similar_data, &SIMILAR_LONG_SAVES),
        ("mortal", mortal_data, &MORTAL_SAVES),
    ];
    for (name, data, saves) in cases {
        for (save, expected) in saves {
            let (world, _) = World::load(&hex(save), data()).expect("loads");
            assert_measures(&world, expected, name);
        }
    }
}

/// Without a living sim there is no measurement ("mortal" after year 5).
#[test]
fn nobody_living_gives_no_measurement() {
    let (world, _) = World::load(&hex(MORTAL_SAVE_EMPTY), mortal_data()).expect("loads");
    assert_eq!(world.state().measure(), None);
}

/// `A` and `G` of genomes with given doses at (`test:g1`, `test:f1`, `test:g2`,
/// `test:p1`): `G` is `A / σ_ref`, the same bits as before the split.
#[test]
fn the_additive_value_is_the_genetic_value_before_the_division() {
    let data = traits_data();
    let copies = |dose: u8| match dose {
        0 => [0, 0],
        1 => [1, 0],
        _ => [1, 1],
    };
    for (doses, expected) in ADDITIVE_VALUES {
        let [g1, f1, g2, p1] = doses;
        let genome = Genome::with_alleles(
            Sex::Female,
            &alleles(&[
                ("test:g1", copies(g1)),
                ("test:f1", copies(f1)),
                ("test:g2", copies(g2)),
                ("test:p1", copies(p1)),
            ]),
            &data,
        )
        .expect("fits");
        for (t, a, g) in expected {
            let a_now = genome.additive_value(&id(t), &data).expect("a trait");
            let g_now = genome.genetic_value(&id(t), &data).expect("a trait");
            assert_eq!(
                (a_now.to_bits(), g_now.to_bits()),
                (a, g),
                "{t} at {doses:?}"
            );
        }
    }
}
